 void event(std::unique_ptr<EventData>e){if(e->kind==0){append(e->text);if(e->text.find(L"WDP_WRITING")!=e->text.npos)status=L"正在烧录，请保持连接…";if(e->text.find(L"WDP_READING_BACK")!=e->text.npos)status=L"正在读回固件并逐字节校验…";}else if(e->kind==1){busy=false;ready=true;connected=e->value!=0;status=e->text;append(e->text);}else if(e->kind==2){busy=false;progressDone=true;status=L"烧录完成 · 读回校验通过";append(status);}else if(e->kind==3){busy=false;connected=false;status=L"操作未完成，请查看下方原因";append(L"失败："+e->text);MessageBeep(MB_ICONWARNING);}else if(e->kind==4){devices=std::move(e->devices);busy=false;status=devices.empty()?L"未发现设备，请确认调试器已上电":L"已找到蓝牙调试器";if(!devices.empty()){bleAddress=devices[0].address;wchar_t address[32];swprintf_s(address,L"%012llX",bleAddress);SetWindowTextW(controls[HOST],address);if(devices.size()>1){HMENU menu=CreatePopupMenu();for(size_t i=0;i<devices.size();i++){std::wstring name=devices[i].name+L" / "+std::to_wstring(devices[i].address);AppendMenuW(menu,MF_STRING,(UINT_PTR)i+1,name.c_str());}POINT pt;GetCursorPos(&pt);int result=TrackPopupMenu(menu,TPM_RETURNCMD,pt.x,pt.y,0,window,nullptr);DestroyMenu(menu);if(result>0){bleAddress=devices[result-1].address;swprintf_s(address,L"%012llX",bleAddress);SetWindowTextW(controls[HOST],address);}}}append(status);}else if(e->kind==5){activeProfile=e->value;selected=e->value;SetWindowTextW(controls[FAMILY],profiles[selected].name);}else if(e->kind==6){DestroyWindow(window);return;}
 enable();InvalidateRect(window,nullptr,FALSE);}
